"""Generate COMMANDS.md: every registry row's command, for the artifact's doc-quote check."""
from __future__ import annotations

import sys
from pathlib import Path

REPO = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REPO))

from bench import reproduce as R  # noqa: E402


def main() -> None:
    lines = ["# Command index", "",
             "Every registry row, the command that reproduces it, and the witness it writes.",
             "Generated by `release/make_commands.py`; `make repro` checks each row against these files.", ""]
    for row in R.ROWS:
        lines += [f"## `{row['id']}`", ""]
        if row.get("table"):
            lines += [f"*{row['table']}*", ""]
        lines += ["```", row["cmd"], "```", ""]
        w = row.get("witness")
        if w:
            w = ", ".join(f"`{x}`" for x in w) if isinstance(w, (list, tuple)) else f"`{w}`"
            lines += [f"Witness: {w}", ""]
    (REPO / "COMMANDS.md").write_text("\n".join(lines) + "\n")
    print(f"wrote COMMANDS.md ({len(R.ROWS)} rows)")


if __name__ == "__main__":
    main()
